from lxml import etree
from zipfile import ZipFile
from six import BytesIO
from robot.api import logger

from . import meta1
from . import meta2
from .decoder import ProtobufDecoder
from .encoder import ProtobufEncoder
from ..exception import InfoModelIms2ReaderDefinitionException


class ManagedObjectsDefinitions(object):

    def __init__(self, meta):
        self.meta = meta
        self.definitions = {}
        self.meta_version = meta2

        # # Optional meta.zip export
        # with open("meta.zip", "wb") as f:
        #     f.write(self.meta)

        meta_zip = ZipFile(BytesIO(self.meta))
        for file_name in meta_zip.namelist():
            if file_name.endswith(".xml"):
                meta_xml = meta_zip.read(file_name)
                doc_root = etree.fromstring(meta_xml)
                self._determine_meta_version(doc_root)
                self._determine_value_encoding(doc_root)
                for elem in doc_root.iter('managedObject'):
                    self.definitions[elem.attrib['class']] = self.meta_version.ManagedObjectDefinition(elem)

    def get_meta(self):
        """Get definitions binary data."""
        return self.meta

    def get_decoder(self, dist_name):
        """Get managed object decoder."""
        definitions_dist_name = self._get_definition(dist_name)
        if not definitions_dist_name:
            raise InfoModelIms2ReaderDefinitionException("Cannot get object definition for: {}\n".format(dist_name))
        return ProtobufDecoder(definitions_dist_name)

    def get_encoder(self, dist_name):
        """Get managed object encoder."""
        return ProtobufEncoder(self._get_definition(dist_name))

    def _get_definition(self, dist_name):
        classname = dist_name.rsplit('/', 1)[1].rsplit('-', 1)[0]
        definitions = self.definitions.get(classname, None)
        if not definitions:
            logger.warn("Cannot get object definition for: {}\n".format(dist_name))
        return definitions

    def _determine_meta_version(self, doc_root):
        if doc_root.find(".//complexType") is not None:
            self.meta_version = meta1

    def _determine_value_encoding(self, doc_root):
        if doc_root.find(".//internal_values_encoding") is not None:
            self.meta_version.INTERNAL_VALUES_ENCODING = True
        else:
            self.meta_version.INTERNAL_VALUES_ENCODING = False
